// Word Builder — the pure data layer. A "record" is one REAL derived word with its parts in order:
//   { id, word, wordId?, gloss, parts:[{ k, form, type, meaning }] }      k = "pre:un-" | "base:kind" | "suf:-ful"
// Records come from (1) the Word Study dataset when that module is present (derivations only, and only those
// isRealDerivation accepts), (2) the unit's own words (morph.segs that really spell the word) and (3) the unit's
// study.parts example lists. Nothing is ever generated by joining letters: a combination is real only if it is a
// record, so a non-word is never shown as a word.
import { clean, norm, tokenize, uniq } from "./text.js";

const KIND = { prefix: "pre", suffix: "suf", base: "base", root: "base", compound: "cmp" };
export const slotType = (t) => (t === "root" ? "base" : t);
export const plainForm = (form) => norm(form).replace(/^-+|-+$/g, "");
const VOWEL = /^[aeiouy]/;

/** Does the ordered list of plain part strings really spell `word`? Allows the three ordinary spelling changes. */
export function spellsWord(plains, word) {
  const w = norm(word);
  let cands = [""];
  for (const raw of plains) {
    const p = plainForm(raw);
    if (!p) return false;
    const next = new Set();
    for (const acc of cands) {
      if (!acc) {
        next.add(p);
        continue;
      }
      next.add(acc + p);
      if (/e$/.test(acc) && VOWEL.test(p)) next.add(acc.slice(0, -1) + p);
      if (/[^aeiou]y$/.test(acc) && !/^i/.test(p)) next.add(`${acc.slice(0, -1)}i${p}`);
      if (/[^aeiou][aeiou][^aeiouwxy]$/.test(acc) && VOWEL.test(p)) next.add(acc + acc.slice(-1) + p);
    }
    cands = [...next];
  }
  return cands.includes(w);
}

const part = (type, form, meaning = "") => ({
  k: `${KIND[type] || "base"}:${norm(form)}`,
  form:
    type === "prefix" || type === "compound"
      ? `${plainForm(form)}${type === "prefix" ? "-" : ""}`
      : type === "suffix"
        ? `-${plainForm(form)}`
        : plainForm(form),
  type: slotType(type),
  meaning: clean(meaning),
});
export const keyOf = (parts) => parts.map((p) => p.k).join("+");

/** Every token the unit's own text uses: the evidence that a stripped base is a real word. */
export function lexiconOf(pool) {
  const set = new Set();
  const add = (text) => {
    for (const t of tokenize(String(text || ""))) if (t.w) set.add(norm(t.t));
  };
  for (const w of pool.all) {
    [
      w.hw,
      w.def,
      w.ex,
      w.ex2,
      w.nonExample,
      w.cloze?.s,
      w.cloze?.f,
      w.cloze2?.s,
      w.rel,
      ...(w.syn || []),
      ...(w.ant || []),
    ].forEach(add);
    for (const f of w.family || []) add(f.w);
    for (const s of w.morph?.segs || []) if (s.t === "base") add(s.s);
  }
  for (const p of pool.passage?.paras || []) add(p);
  for (const p of pool.study?.parts || []) (p.ex || []).forEach(add);
  return set;
}

/** Records from unit words whose authored morph.segs spell the word. */
export function recordsFromWords(pool) {
  const out = [];
  for (const w of pool.all) {
    const segs = (w.morph?.segs || []).filter((s) => s.s && s.t);
    if (segs.length < 2 || segs.length > 4) continue;
    if (!segs.some((s) => s.t === "prefix" || s.t === "suffix")) continue;
    if (
      !spellsWord(
        segs.map((s) => s.s),
        w.hw,
      )
    )
      continue;
    out.push({
      id: `w:${w.id}`,
      word: w.hw,
      wordId: w.id,
      gloss: clean(w.def),
      parts: segs.map((s) => part(s.t, s.s, s.m)),
    });
  }
  return out;
}

/** Records from the unit's study.parts example words, accepted only when the base is a word the unit itself uses. */
export function recordsFromStudy(pool) {
  const lex = lexiconOf(pool);
  const out = [];
  const byHw = new Map(pool.all.map((w) => [norm(w.hw), w]));
  for (const p of pool.study?.parts || []) {
    if (!["prefix", "suffix", "compound"].includes(p.type) || !p.p) continue;
    const plain = plainForm(p.p);
    if (plain.length < 2 && p.type !== "suffix") continue;
    for (const ex of p.ex || []) {
      const w = norm(ex);
      let bases = [];
      if (p.type === "suffix") {
        if (!w.endsWith(plain) || w.length <= plain.length + 1) continue;
        const stem = w.slice(0, -plain.length);
        bases = uniq([stem, `${stem}e`, stem.slice(0, -1), `${stem.slice(0, -1)}y`]);
      } else {
        if (!w.startsWith(plain) || w.length <= plain.length + 1) continue;
        bases = [w.slice(plain.length)];
      }
      const base = bases.find(
        (b) =>
          b.length >= 2 &&
          lex.has(b) &&
          spellsWord(p.type === "suffix" ? [b, plain] : [plain, b], w),
      );
      if (!base) continue;
      const own = byHw.get(w);
      const parts =
        p.type === "suffix"
          ? [part("base", base), part("suffix", plain, p.m)]
          : [part(p.type, plain, p.m), part("base", base)];
      out.push({ id: `s:${w}`, word: w, wordId: own?.id, gloss: own ? clean(own.def) : "", parts });
    }
  }
  return out;
}

/** Records from the Word Study dataset (SPEC 3.4). `isReal` is wordstudy.isRealDerivation when it exists. */
export function recordsFromDataset(dataset, pool, isReal) {
  if (!dataset || !Array.isArray(dataset.derivations)) return [];
  const byId = new Map((dataset.parts || []).map((p) => [p.id, p]));
  const byHw = new Map(pool.all.map((w) => [norm(w.hw), w]));
  const out = [];
  for (const d of dataset.derivations) {
    if (!d?.word || !Array.isArray(d.parts) || d.parts.length < 2) continue;
    if (typeof isReal === "function") {
      try {
        if (isReal(d.parts) === false) continue;
      } catch {}
    }
    const parts = [];
    let bad = false;
    for (const id of d.parts) {
      if (String(id).startsWith("base:")) parts.push(part("base", String(id).slice(5)));
      else {
        const p = byId.get(id);
        if (!p || !["prefix", "suffix", "root", "base"].includes(p.type)) {
          bad = true;
          break;
        }
        const grades = Array.isArray(p.grades) && p.grades.length ? p.grades : null;
        if (grades && !grades.map(String).includes(String(pool.grade))) bad = true;
        parts.push(part(p.type, p.form, p.meaning));
      }
    }
    if (
      bad ||
      !spellsWord(
        parts.map((p) => p.form),
        d.word,
      )
    )
      continue;
    const own = byHw.get(norm(d.word));
    out.push({
      id: `d:${norm(d.word)}`,
      word: norm(d.word),
      wordId: own?.id,
      gloss: clean(d.gloss || (own ? own.def : "")),
      parts,
    });
  }
  return out;
}

/** All records for a pool, unit-own first (so the run is about THIS unit), one per word. */
export function buildRecords(pool, { dataset, isReal } = {}) {
  const own = [...recordsFromWords(pool), ...recordsFromStudy(pool)];
  const ds = recordsFromDataset(dataset, pool, isReal);
  const seen = new Set();
  const all = [];
  for (const r of [...own, ...ds]) {
    const k = norm(r.word);
    if (seen.has(k)) continue;
    seen.add(k);
    all.push(r);
  }
  // Dataset words only fill in when they share a part with the unit, or are the unit's own words.
  const unitParts = new Set(
    own.flatMap((r) => r.parts.filter((p) => p.type !== "base").map((p) => p.k)),
  );
  return all.filter(
    (r) =>
      own.includes(r) || r.wordId || r.parts.some((p) => unitParts.has(p.k)) || own.length === 0,
  );
}
/** Keys of every real combination we can vouch for (the dataset in full, not just the chosen records). */
export function validKeys(records, dataset, pool) {
  const map = new Map(records.map((r) => [keyOf(r.parts), r]));
  for (const r of recordsFromDataset(dataset, pool))
    if (!map.has(keyOf(r.parts))) map.set(keyOf(r.parts), r);
  return map;
}
